IDS = ["LY-517","LY-518","LY-519","LY-520","LY-521","LY-522","LY-523","LY-524","LY-525","LY-526",
       "LY-527","LY-528","LY-529","LY-530","LY-531","LY-532","LY-533","LY-534","LY-535","LY-536"]
assert set(PREDS) == set(IDS), (set(PREDS) ^ set(IDS))
for cid in IDS:
    p = PREDS[cid]
    rec = {"case_id": cid, "prediction_text": p["prediction_text"], "basis": p["basis"],
           "confidence": p["confidence"], "trigger": p["trigger"]}
    assert rec["basis"].splitlines()[0] == "liuyao", cid
    assert 0.0 <= rec["confidence"] <= 1.0
    t = rec["trigger"]
    assert set(t) == {"changed_main","reserve_used","disputed","reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))
    f = OUT / f"{cid}.json"
    f.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    back = json.loads(f.read_text(encoding="utf-8"))
    assert back["case_id"] == cid and back["prediction_text"] and back["basis"]
    print(cid, f.stat().st_size)
print("TOTAL", len(IDS))
print("changed_main", sum(PREDS[c]["trigger"]["changed_main"] for c in IDS))
print("reserve_used", sum(PREDS[c]["trigger"]["reserve_used"] for c in IDS))
print("disputed", sum(PREDS[c]["trigger"]["disputed"] for c in IDS))
